package io.github.ogshrug.flatdocscanner

import android.app.Activity
import android.app.Application
import android.os.Bundle
import androidx.annotation.StringRes
import androidx.annotation.StyleRes
import androidx.appcompat.app.AppCompatDelegate
import java.util.WeakHashMap

/**
 * The colour themes a user can pick. Each is a style overlay (theme_overlays.xml, generated by
 * tools/make_themes.py) laid over Theme.DocScanner; its colours have a light and a dark set.
 * Teal is the app's own; the others follow Astryx, Meta's open-source design system.
 */
enum class AppTheme(val key: String, @param:StringRes val label: Int, @param:StyleRes val overlay: Int) {
    TEAL("teal", R.string.theme_teal, R.style.ThemeOverlay_DocScanner_Teal),
    NEUTRAL("neutral", R.string.theme_neutral, R.style.ThemeOverlay_DocScanner_Neutral),
    STONE("stone", R.string.theme_stone, R.style.ThemeOverlay_DocScanner_Stone),
    BUTTER("butter", R.string.theme_butter, R.style.ThemeOverlay_DocScanner_Butter),
    CHOCOLATE("chocolate", R.string.theme_chocolate, R.style.ThemeOverlay_DocScanner_Chocolate),
    MATCHA("matcha", R.string.theme_matcha, R.style.ThemeOverlay_DocScanner_Matcha),
    GOTHIC("gothic", R.string.theme_gothic, R.style.ThemeOverlay_DocScanner_Gothic),
    Y2K("y2k", R.string.theme_y2k, R.style.ThemeOverlay_DocScanner_Y2k);

    companion object {
        fun of(key: String?) = entries.firstOrNull { it.key == key } ?: TEAL
    }
}

/** Light, dark, or whatever the phone is set to. */
enum class Appearance(val key: String, @param:StringRes val label: Int, val nightMode: Int) {
    SYSTEM("system", R.string.appearance_system, AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM),
    LIGHT("light", R.string.appearance_light, AppCompatDelegate.MODE_NIGHT_NO),
    DARK("dark", R.string.appearance_dark, AppCompatDelegate.MODE_NIGHT_YES);

    companion object {
        fun of(key: String?) = entries.firstOrNull { it.key == key } ?: DARK
    }
}

/**
 * Puts the chosen theme on every activity as it is created, and re-creates an activity that
 * comes back to the front after the theme was changed elsewhere (the library, when Settings
 * closes). Light or dark is AppCompat's night mode, which re-creates activities by itself.
 */
object Themes : Application.ActivityLifecycleCallbacks {

    private val shown = WeakHashMap<Activity, AppTheme>()

    fun install(app: Application) {
        AppCompatDelegate.setDefaultNightMode(app.settings.appearance.nightMode)
        app.registerActivityLifecycleCallbacks(this)
    }

    fun setAppearance(activity: Activity, appearance: Appearance) {
        activity.settings.appearance = appearance
        AppCompatDelegate.setDefaultNightMode(appearance.nightMode)
    }

    fun setTheme(activity: Activity, theme: AppTheme) {
        activity.settings.theme = theme
        activity.recreate()
    }

    /**
     * Lays the overlay on the activity's theme. Not Activity.setTheme: AppCompat records the
     * id passed there as "the" theme and re-applies it when it switches between light and
     * dark, which would leave the base theme built for the wrong one.
     */
    private fun apply(activity: Activity) {
        val theme = activity.settings.theme
        activity.theme.applyStyle(theme.overlay, true)
        shown[activity] = theme
    }

    // Before the activity's own onCreate, so anything it reads early is already themed.
    override fun onActivityPreCreated(activity: Activity, savedInstanceState: Bundle?) = apply(activity)

    // And again once super.onCreate() has run: that is where AppCompat settles light or dark
    // and re-applies the base theme, over the overlay. This still precedes setContentView.
    // (Before Android 10 this is the only one of the two that is called.)
    override fun onActivityCreated(activity: Activity, savedInstanceState: Bundle?) = apply(activity)

    override fun onActivityResumed(activity: Activity) {
        if (shown[activity] != activity.settings.theme) activity.recreate()
    }

    override fun onActivityStarted(activity: Activity) = Unit
    override fun onActivityPaused(activity: Activity) = Unit
    override fun onActivityStopped(activity: Activity) = Unit
    override fun onActivitySaveInstanceState(activity: Activity, outState: Bundle) = Unit
    override fun onActivityDestroyed(activity: Activity) = Unit
}
